arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="Engineering insights, product updates, and community stories from DeployCloud." />
  <style>
    :root {
      --bg: #fafafa;
      --surface: #ffffff;
      --surface-soft: #f4f6f8;
      --text: #171717;
      --muted: #666f7a;
      --subtle: #8a929e;
      --line: #e7e9ee;
      --line-strong: #d8dde5;
      --accent: #0072f5;
      --accent-2: #ff7a1a;
      --navy: #071226;
      --shadow: 0 18px 50px rgba(10, 22, 50, .08);
      --shadow-lg: 0 28px 80px rgba(10, 22, 50, .14);
      --radius: 22px;
      --radius-sm: 14px;
      --max: 1200px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(0, 114, 245, .08), transparent 34rem),
        linear-gradient(180deg, #ffffff 0%, var(--bg) 48%, #fff 100%);
      color: var(--text);
      line-height: 1.55;
    }
    a { color: inherit; text-decoration: none; }
    button, input { font: inherit; }
    .container { width: min(var(--max), calc(100% - 40px)); margin: 0 auto; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 50;
      background: rgba(255,255,255,.82);
      backdrop-filter: blur(18px);
      border-bottom: 1px solid rgba(231,233,238,.8);
    }
    .nav {
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 22px;
    }
    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 760;
      letter-spacing: -.03em;
      white-space: nowrap;
    }
    .brand-mark {
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 10px;
      color: #fff;
      background: conic-gradient(from 220deg, var(--accent), #21d4fd, #13294b, var(--accent));
      box-shadow: 0 10px 25px rgba(0,114,245,.24);
    }
    .nav-links, .nav-actions { display: flex; align-items: center; gap: 8px; }
    .nav-link, .nav-btn {
      border: 0;
      background: transparent;
      padding: 9px 11px;
      border-radius: 999px;
      color: #303844;
      cursor: pointer;
      font-size: 14px;
    }
    .nav-link:hover, .nav-btn:hover, .dropdown.open .nav-btn { background: var(--surface-soft); color: var(--text); }
    .nav-btn::after { content: "⌄"; margin-left: 6px; color: var(--subtle); }
    .action-ghost { color: #404854; font-size: 14px; padding: 8px 10px; border-radius: 999px; }
    .action-ghost:hover { background: var(--surface-soft); }
    .signup {
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      padding: 9px 15px;
      font-size: 14px;
      box-shadow: 0 10px 26px rgba(23,23,23,.14);
    }
    .dropdown { position: relative; }
    .mega {
      position: absolute;
      top: calc(100% + 12px);
      left: 50%;
      transform: translateX(-50%) translateY(8px);
      width: min(760px, calc(100vw - 32px));
      background: rgba(255,255,255,.96);
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow-lg);
      padding: 18px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      opacity: 0;
      pointer-events: none;
      transition: .18s ease;
    }
    .dropdown.open .mega, .dropdown:hover .mega {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega.resources { width: min(640px, calc(100vw - 32px)); }
    .mega-col { padding: 12px; border-radius: 18px; background: linear-gradient(180deg, #fff, #fbfcfe); }
    .mega-title { margin: 0 0 10px; font-size: 12px; font-weight: 800; color: var(--accent); text-transform: uppercase; letter-spacing: .08em; }
    .mega-item { display: block; padding: 9px 8px; border-radius: 12px; }
    .mega-item:hover { background: var(--surface-soft); }
    .mega-item strong { display: block; font-size: 14px; letter-spacing: -.01em; }
    .mega-item span { display: block; color: var(--muted); font-size: 12px; margin-top: 1px; }

    .hero { padding: 78px 0 26px; }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      border: 1px solid rgba(0,114,245,.16);
      background: rgba(0,114,245,.07);
      color: #0057c2;
      border-radius: 999px;
      padding: 7px 12px;
      font-weight: 700;
      font-size: 13px;
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.16fr .84fr;
      gap: 42px;
      align-items: end;
      margin-top: 20px;
    }
    h1 {
      margin: 0;
      max-width: 820px;
      font-size: clamp(46px, 7vw, 88px);
      line-height: .94;
      letter-spacing: -.075em;
    }
    .hero-copy { margin: 0; color: #4b5563; font-size: clamp(17px, 2vw, 21px); max-width: 560px; }
    .hero-panel {
      background: var(--navy);
      color: #fff;
      border-radius: 28px;
      padding: 22px;
      box-shadow: var(--shadow-lg);
      position: relative;
      overflow: hidden;
    }
    .hero-panel::before {
      content: "";
      position: absolute;
      inset: -80px -90px auto auto;
      width: 210px;
      height: 210px;
      border-radius: 999px;
      background: rgba(0,114,245,.45);
      filter: blur(18px);
    }
    .panel-label { color: #a9caff; font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }
    .panel-number { margin: 10px 0 0; font-size: 48px; line-height: 1; letter-spacing: -.05em; font-weight: 850; }
    .panel-copy { margin: 10px 0 18px; color: #cbd5e1; }
    .mini-stats { display: grid; grid-template-columns: repeat(2,1fr); gap: 10px; }
    .mini-stat { border: 1px solid rgba(255,255,255,.12); border-radius: 16px; padding: 12px; background: rgba(255,255,255,.05); }
    .mini-stat strong { display: block; font-size: 20px; }
    .mini-stat span { color: #b6c2d3; font-size: 12px; }

    .filters-wrap { padding: 22px 0 34px; }
    .filters-bar {
      display: grid;
      grid-template-columns: 1fr 300px;
      gap: 18px;
      align-items: center;
      background: rgba(255,255,255,.76);
      border: 1px solid var(--line);
      border-radius: 24px;
      padding: 12px;
      box-shadow: 0 8px 32px rgba(10,22,50,.04);
    }
    .filters { display: flex; flex-wrap: wrap; gap: 8px; }
    .pill {
      border: 1px solid var(--line);
      background: #fff;
      color: #343c47;
      border-radius: 999px;
      padding: 9px 13px;
      cursor: pointer;
      font-size: 14px;
      transition: .15s ease;
    }
    .pill:hover { border-color: #b9c5d6; transform: translateY(-1px); }
    .pill.active { background: var(--accent); color: #fff; border-color: var(--accent); box-shadow: 0 10px 24px rgba(0,114,245,.22); }
    .search { position: relative; }
    .search input {
      width: 100%;
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 999px;
      padding: 11px 14px 11px 40px;
      outline: 0;
      color: var(--text);
    }
    .search input:focus { border-color: rgba(0,114,245,.48); box-shadow: 0 0 0 4px rgba(0,114,245,.09); }
    .search::before { content: "⌕"; position: absolute; left: 15px; top: 50%; transform: translateY(-54%); color: var(--subtle); z-index: 1; }

    .section-head { display: flex; justify-content: space-between; align-items: end; gap: 24px; margin: 34px 0 20px; }
    .section-kicker { color: var(--accent); font-size: 13px; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
    h2 { margin: 4px 0 0; font-size: clamp(30px, 4vw, 48px); line-height: 1; letter-spacing: -.055em; }
    .section-head p { color: var(--muted); max-width: 440px; margin: 0; }

    .featured-grid { display: grid; grid-template-columns: 1.2fr .9fr .9fr; gap: 18px; }
    .featured-card, .post-card {
      border: 1px solid var(--line);
      background: var(--surface);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: 0 10px 34px rgba(10,22,50,.05);
      transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
    }
    .featured-card:hover, .post-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); border-color: var(--line-strong); }
    .featured-card { min-height: 430px; display: flex; flex-direction: column; position: relative; }
    .featured-card.primary { background: linear-gradient(145deg, #071226, #10294f 54%, #0072f5); color: #fff; grid-row: span 2; }
    .featured-card.primary::after {
      content: "";
      position: absolute;
      inset: auto -70px -90px auto;
      width: 230px;
      height: 230px;
      border-radius: 50%;
      background: rgba(255,255,255,.17);
    }
    .card-art {
      height: 145px;
      background:
        linear-gradient(135deg, rgba(0,114,245,.14), rgba(255,122,26,.08)),
        repeating-linear-gradient(135deg, transparent 0 16px, rgba(0,0,0,.035) 16px 17px);
      border-bottom: 1px solid var(--line);
    }
    .primary .card-art { height: 175px; border-color: rgba(255,255,255,.14); background: radial-gradient(circle at 20% 30%, rgba(255,255,255,.35), transparent 28%), linear-gradient(135deg, rgba(255,255,255,.06), rgba(255,255,255,.18)); }
    .card-body { padding: 22px; display: flex; flex-direction: column; flex: 1; position: relative; z-index: 1; }
    .meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; margin-bottom: 13px; }
    .primary .meta, .primary .excerpt, .primary .author span { color: #d6e5ff; }
    .tag { display: inline-flex; align-items: center; border-radius: 999px; padding: 4px 9px; background: rgba(0,114,245,.09); color: #005fd1; font-weight: 800; font-size: 12px; }
    .primary .tag { background: rgba(255,255,255,.16); color: #fff; }
    h3 { margin: 0; font-size: 24px; line-height: 1.08; letter-spacing: -.045em; }
    .primary h3 { font-size: clamp(32px, 4vw, 46px); }
    .excerpt { color: #56606c; margin: 13px 0 20px; }
    .author { display: flex; align-items: center; gap: 10px; margin-top: auto; font-size: 14px; font-weight: 740; }
    .avatar {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, #eaf3ff, #fff1e8);
      color: #0f274a;
      border: 1px solid rgba(0,0,0,.06);
      font-size: 12px;
      font-weight: 850;
      flex: 0 0 auto;
    }
    .primary .avatar { background: rgba(255,255,255,.18); color: #fff; border-color: rgba(255,255,255,.25); }
    .stat-ribbon { display: flex; gap: 8px; flex-wrap: wrap; margin: 6px 0 17px; }
    .stat-chip { border-radius: 999px; padding: 7px 10px; background: rgba(255,255,255,.13); color: #fff; font-weight: 780; font-size: 12px; }

    .latest { padding: 34px 0 0; }
    .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
    .post-card { display: flex; flex-direction: column; min-height: 315px; }
    .post-card .card-art { height: 118px; }
    .post-card h3 { font-size: 21px; }
    .post-card .excerpt { font-size: 14px; }
    .empty {
      display: none;
      border: 1px dashed #cbd5e1;
      border-radius: 24px;
      padding: 44px 20px;
      text-align: center;
      color: var(--muted);
      background: #fff;
      grid-column: 1 / -1;
    }
    .empty strong { display: block; color: var(--text); font-size: 22px; margin-bottom: 6px; letter-spacing: -.03em; }
    .load-wrap { text-align: center; padding: 28px 0 22px; }
    .load-more {
      border: 1px solid #111827;
      background: #111827;
      color: #fff;
      border-radius: 999px;
      padding: 12px 18px;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(17,24,39,.16);
    }
    .load-more:hover { transform: translateY(-1px); }
    .load-more[hidden] { display: none; }

    .cta { padding: 64px 0 54px; }
    .cta-grid {
      display: grid;
      grid-template-columns: 1.35fr .65fr;
      gap: 18px;
    }
    .cta-main, .enterprise {
      border-radius: 30px;
      padding: clamp(26px, 4vw, 42px);
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
    }
    .cta-main { background: linear-gradient(135deg, #071226, #10294f); color: #fff; }
    .cta-main h2 { max-width: 780px; }
    .cta-main p { color: #cbd5e1; font-size: 18px; max-width: 720px; }
    .cta-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; border-radius: 999px; padding: 12px 17px; font-weight: 800; }
    .btn.primary { background: #fff; color: #071226; }
    .btn.secondary { border: 1px solid rgba(255,255,255,.28); color: #fff; }
    .enterprise { background: #fff; display: flex; flex-direction: column; justify-content: space-between; }
    .enterprise h3 { font-size: 27px; }
    .enterprise p { color: var(--muted); }
    .enterprise .btn { background: var(--accent); color: #fff; align-self: flex-start; }

    footer { border-top: 1px solid var(--line); background: #fff; padding: 42px 0 28px; }
    .footer-top { display: flex; justify-content: space-between; gap: 20px; align-items: center; margin-bottom: 30px; }
    .status { display: inline-flex; align-items: center; gap: 8px; color: #177245; font-size: 14px; font-weight: 760; }
    .status::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 0 5px rgba(34,197,94,.12); }
    .footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px 18px; }
    .footer-col h4 { margin: 0 0 10px; font-size: 13px; letter-spacing: -.01em; }
    .footer-col a { display: block; color: var(--muted); font-size: 13px; padding: 3px 0; }
    .footer-col a:hover { color: var(--accent); }

    @media (max-width: 960px) {
      .nav-links { display: none; }
      .hero-grid, .filters-bar, .cta-grid { grid-template-columns: 1fr; }
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-card.primary { grid-column: 1 / -1; min-height: 380px; }
      .grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }
    @media (max-width: 640px) {
      .container { width: min(100% - 28px, var(--max)); }
      .hero { padding-top: 46px; }
      .nav { height: 64px; }
      .nav-actions .action-ghost:not(:first-child) { display: none; }
      .signup { padding: 8px 12px; }
      .section-head { display: block; }
      .section-head p { margin-top: 10px; }
      .featured-grid, .grid { grid-template-columns: 1fr; }
      .featured-card, .featured-card.primary { min-height: auto; }
      .mini-stats { grid-template-columns: 1fr; }
      .footer-top { display: block; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container nav">
      <a class="brand" href="./index.html" aria-label="DeployCloud Blog home"><span class="brand-mark">▲</span><span>DeployCloud</span></a>
      <nav class="nav-links" aria-label="Main navigation">
        <div class="dropdown" data-dropdown>
          <button class="nav-btn" type="button" aria-expanded="false">Products</button>
          <div class="mega" role="menu">
            <div class="mega-col"><p class="mega-title">AI Cloud</p><a class="mega-item" href="#"><strong>AI Gateway</strong><span>One endpoint, all your models</span></a><a class="mega-item" href="#"><strong>Sandbox</strong><span>Isolated, safe code execution</span></a><a class="mega-item" href="#"><strong>DeployCloud Agent</strong><span>An agent that knows your stack</span></a><a class="mega-item" href="#"><strong>AI SDK</strong><span>The AI Toolkit for TypeScript</span></a><a class="mega-item" href="#"><strong>v0</strong><span>Build applications with AI</span></a></div>
            <div class="mega-col"><p class="mega-title">Core Platform</p><a class="mega-item" href="#"><strong>CI/CD</strong><span>Helping teams ship 6× faster</span></a><a class="mega-item" href="#"><strong>Content Delivery</strong><span>Fast, scalable, and reliable</span></a><a class="mega-item" href="#"><strong>Fluid Compute</strong><span>Servers, in serverless form</span></a><a class="mega-item" href="#"><strong>Workflows</strong><span>Long-running workflows at scale</span></a><a class="mega-item" href="#"><strong>Observability</strong><span>Trace every step</span></a></div>
            <div class="mega-col"><p class="mega-title">Security</p><a class="mega-item" href="#"><strong>Bot Management</strong></a><a class="mega-item" href="#"><strong>BotID</strong></a><a class="mega-item" href="#"><strong>Platform Security</strong></a><a class="mega-item" href="#"><strong>Web Application Firewall</strong></a></div>
          </div>
