        <div class="dropdown" data-dropdown>
          <button class="nav-btn" type="button" aria-expanded="false">Resources</button>
          <div class="mega resources" role="menu">
            <div class="mega-col"><p class="mega-title">Company</p><a class="mega-item" href="#"><strong>Customers</strong></a><a class="mega-item" href="#"><strong>Blog</strong></a><a class="mega-item" href="#"><strong>Changelog</strong></a><a class="mega-item" href="#"><strong>Press</strong></a><a class="mega-item" href="#"><strong>Events</strong></a></div>
            <div class="mega-col"><p class="mega-title">Learn</p><a class="mega-item" href="#"><strong>Docs</strong></a><a class="mega-item" href="#"><strong>Academy</strong></a><a class="mega-item" href="#"><strong>Knowledge Base</strong></a><a class="mega-item" href="#"><strong>Community</strong></a></div>
            <div class="mega-col"><p class="mega-title">Open Source</p><a class="mega-item" href="#"><strong>Next.js</strong></a><a class="mega-item" href="#"><strong>Nuxt</strong></a><a class="mega-item" href="#"><strong>Svelte</strong></a><a class="mega-item" href="#"><strong>Turborepo</strong></a></div>
          </div>
        </div>
        <a class="nav-link" href="#">Solutions</a><a class="nav-link" href="#">Enterprise</a><a class="nav-link" href="#">Pricing</a>
      </nav>
      <div class="nav-actions"><a class="action-ghost" href="#">Ask AI</a><a class="action-ghost" href="#">Log In</a><a class="signup" href="#">Sign Up</a></div>
    </div>
