      <div class="footer-grid" id="footerGrid"></div>
    </div>
  </footer>

  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "v0", "Security", "Changelog", "Press"];
    const featured = [
      { title: "Agentic Infrastructure", category: "Engineering", date: "Apr 9", author: "Tom Reeves", excerpt: "Every generation of software eventually demands a new generation of infrastructure. LLMs and coding agents are driving the next transition, and it's happening fast.", stats: ["30% of deployments", "1000% increase", "20× AI inference"] },
      { title: "A new programming model for durable execution", category: "Engineering", date: "Apr 16", author: "Pranav Mehta", excerpt: "The gap between prototypes and production-ready systems is huge. Workflows extends framework-defined infrastructure to long-running systems." },
      { title: "Agent responsibly", category: "Community", date: "Mar 30", author: "Matthew Carr", excerpt: "Coding agents generate code at unprecedented speeds — but without rigorous judgment, they are a fast way to ship bad assumptions directly to production." }
    ];
    const posts = [
      { title: "A new programming model for durable execution", category: "Engineering", date: "Apr 16", author: "Pranav Mehta", excerpt: "Code that's trivial to run locally falls apart when it handles failures, restarts, and real traffic. Workflows extends that model." },
      { title: "Agentic Infrastructure", category: "Engineering", date: "Apr 9", author: "Tom Reeves", excerpt: "30% of deployments are initiated by coding agents, a 1000% increase from six months ago, changing what infrastructure must become." },
      { title: "Zero Data Retention on AI Gateway", category: "Security", date: "Apr 6", author: "Jerlyn and Dan", excerpt: "Building with multiple AI models means wrestling with fragmented data policies. AI Gateway brings clearer controls to every provider." },
      { title: "Optimizing Sandbox snapshots", category: "Engineering", date: "Apr 2", author: "Tom, Rob, and 2 others", excerpt: "When we shipped filesystem snapshots in Sandbox, teams could capture and restore code execution environments faster and safer." },
      { title: "How a startup made a blog platform work for humans and AI alike", category: "Customers", date: "Apr 1", author: "Nic Vargas", excerpt: "A two-person, YC-backed startup built an agentic CMS for businesses that keeps editorial judgment and machine speed aligned." },
      { title: "Making build tool 96% faster with agents, sandboxes, and humans", category: "Engineering", date: "Mar 30", author: "Anthony Shew", excerpt: "Build tool is now 81–91% faster to compute task graphs in our repositories, scaling with repo size and real developer workflows." },
      { title: "Unified reporting for all AI Gateway usage", category: "Company News", date: "Mar 25", author: "Jerlyn and Dan", excerpt: "If you're shipping AI features, you already have usage data. The problem is that it's spread across providers, keys, and environments." },
      { title: "Agent responsibly", category: "Community", date: "Mar 30", author: "Matthew Carr", excerpt: "A practical framework for teams shipping with agents, from review rituals to assumptions that should never reach production unchecked." },
      { title: "v0 workflows for design engineers", category: "v0", date: "Mar 21", author: "DeployCloud Design", excerpt: "How design engineers prototype interface states, connect components, and hand off production-ready foundations with v0." },
      { title: "DeployCloud Changelog: spring platform updates", category: "Changelog", date: "Mar 18", author: "Platform Team", excerpt: "New observability views, faster cache priming, improved domain onboarding, and refinements across the deployment dashboard." },
      { title: "Press: DeployCloud expands AI Cloud", category: "Press", date: "Mar 12", author: "Communications", excerpt: "DeployCloud announces expanded AI Gateway availability, Sandbox improvements, and new controls for enterprise teams." },
      { title: "Community templates for every framework", category: "Community", date: "Mar 7", author: "Maya Chen", excerpt: "Nuxt, Svelte, Next.js, and Nitro starters from the community make it faster to ship production-grade applications." }
    ];
    const footers = {
      "Get Started": ["Templates", "Supported Frameworks", "Marketplace", "Domains"],
      "Build": ["Next.js on DeployCloud", "Turborepo", "v0"],
      "Scale": ["Content Delivery Network", "Fluid Compute", "CI/CD", "Observability", "AI Gateway", "DeployCloud Agent"],
      "Secure": ["Platform Security", "Web Application Firewall", "Bot Management", "BotID", "Sandbox"],
      "Resources": ["Pricing", "Customers", "Enterprise", "Articles", "Startups", "Solution Partners"],
      "Learn": ["Docs", "Blog", "Changelog", "Knowledge Base", "Academy", "Community"],
      "Frameworks": ["Next.js", "Nuxt", "Svelte", "Nitro", "Turbo"],
      "SDKs": ["AI SDK", "Workflow SDK", "Flags SDK", "Chat SDK", "Streamdown AI"],
      "Use Cases": ["Composable Commerce", "Multi-tenant Platforms", "Web Apps", "Marketing Sites", "Platform Engineers", "Design Engineers"],
      "Company": ["About", "Careers", "Help", "Press", "Legal", "Privacy Policy"],
      "Community": ["Open Source Program", "Events", "GitHub", "LinkedIn", "X", "YouTube"]
    };

    let activeCategory = "All Posts";
    let query = "";
    let visibleCount = 6;

    const initials = name => name.split(/\s|and|,/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
    const postMatches = post => (activeCategory === "All Posts" || post.category === activeCategory) && `${post.title} ${post.category} ${post.author} ${post.excerpt}`.toLowerCase().includes(query);
    const card = (post, type = "post", index = 0) => `
      <article class="${type === "featured" ? `featured-card ${index === 0 ? "primary" : ""}` : "post-card"}">
        <div class="card-art" aria-hidden="true"></div>
        <div class="card-body">
          <div class="meta"><span class="tag">${post.category}</span><span>${post.date}</span></div>
          <h3>${post.title}</h3>
          ${post.stats ? `<div class="stat-ribbon">${post.stats.map(stat => `<span class="stat-chip">${stat}</span>`).join("")}</div>` : ""}
          <p class="excerpt">${post.excerpt}</p>
          <div class="author"><span class="avatar">${initials(post.author)}</span><span>By ${post.author}</span></div>
        </div>
      </article>`;

    function renderFilters() {
      document.getElementById("filters").innerHTML = categories.map(category => `<button class="pill ${category === activeCategory ? "active" : ""}" type="button" data-category="${category}">${category}</button>`).join("");
    }
    function renderFeatured() {
      document.getElementById("featuredGrid").innerHTML = featured.map((post, index) => card(post, "featured", index)).join("");
    }
    function renderPosts() {
      const filtered = posts.filter(postMatches);
      const shown = filtered.slice(0, visibleCount);
      document.getElementById("postGrid").innerHTML = shown.map(post => card(post)).join("") + document.getElementById("emptyState").outerHTML;
      document.getElementById("emptyState").style.display = filtered.length ? "none" : "block";
      const loadMore = document.getElementById("loadMore");
      loadMore.hidden = filtered.length <= visibleCount;
      loadMore.textContent = `Show more posts${filtered.length > visibleCount ? ` (${filtered.length - visibleCount})` : ""}`;
    }
    function renderFooter() {
      document.getElementById("footerGrid").innerHTML = Object.entries(footers).map(([title, links]) => `<div class="footer-col"><h4>${title}</h4>${links.map(link => `<a href="#">${link}</a>`).join("")}</div>`).join("");
    }

    document.addEventListener("click", event => {
      const dropdownButton = event.target.closest("[data-dropdown] .nav-btn");
      document.querySelectorAll("[data-dropdown]").forEach(dropdown => {
        if (!dropdown.contains(event.target)) {
          dropdown.classList.remove("open");
          dropdown.querySelector("button").setAttribute("aria-expanded", "false");
        }
      });
      if (dropdownButton) {
        const dropdown = dropdownButton.closest("[data-dropdown]");
        dropdown.classList.toggle("open");
        dropdownButton.setAttribute("aria-expanded", dropdown.classList.contains("open"));
      }
      const filter = event.target.closest("[data-category]");
      if (filter) {
        activeCategory = filter.dataset.category;
        visibleCount = 6;
        renderFilters();
        renderPosts();
      }
    });
    document.getElementById("searchInput").addEventListener("input", event => {
      query = event.target.value.trim().toLowerCase();
      visibleCount = 6;
      renderPosts();
    });
    document.getElementById("loadMore").addEventListener("click", () => {
      visibleCount += 3;
      renderPosts();
    });

    renderFilters();
    renderFeatured();
    renderPosts();
    renderFooter();
  </script>
</body>
</html>
EOF

